    int t;
    scanf("%d", &t);
    // Вычислите часы и минуты и напечатайте ЧЧ:ММ.
    return 0;
}

additionalExercises.referenceSolution:
#include <stdio.h>

int main(void) {
    int t;
    scanf("%d", &t);
    int hours = t / 60;
    int minutes = t - hours * 60;
    printf("%02d:%02d\n", hours, minutes);
    return 0;
}

