additionalExercises.referenceSolution:
#include <stdio.h>

int main(void) {
    int bread, milk, cheese;
    scanf("%d %d %d", &bread, &milk, &cheese);
    int total = bread + milk + cheese;
    printf("%5d  Хлеб\n", bread);
    printf("%5d  Молоко\n", milk);
    printf("%5d  Сыр\n", cheese);
    printf("%5d  Итого\n", total);
    return 0;
}

