additionalExercises.referenceSolution:
#include <stdio.h>

int main(void) {
    int done, total;
    scanf("%d %d", &done, &total);
    int percent = done * 100 / total;
    printf("Готово: %d/%d (%d%%)\n", done, total, percent);
    return 0;
}

